# Generate test/dash_v24_testnet_versionbits.inc from the tn-v24-probe header dumps.
import json, sys
out_path = sys.argv[1]
d = {}
for f in sys.argv[2:]:
    d.update({int(k): v for k, v in json.load(open(f)).items()})
lo, hi = min(d), max(d)
assert all(h in d for h in range(lo, hi + 1))
P = 100
L = []
L.append("// SPDX-License-Identifier: AGPL-3.0-or-later")
L.append("// Dash testnet header facts around the Dash Core v24 activation, for the")
L.append("// versionbits replay KAT (test_dash_v24_deployments.cpp). Generated by")
L.append("// test/fixtures/dash_v24/gen_tn_vb_fixture.py from public testnet headers")
L.append("// (Insight API, node 240000) captured on 2026-11-06, heights %d..%d." % (lo, hi))
L.append("// Every header in the range has nVersion 0x20000000 except the bit-13")
L.append("// ranges below (0x20002000). No header sets bit 14.")
L.append("#pragma once")
L.append("#include <cstdint>")
L.append("namespace dash_v24_tn_fixture {")
L.append("inline constexpr uint32_t kFirstHeight = %d;" % lo)
L.append("inline constexpr uint32_t kLastHeight = %d;" % hi)
# signalling ranges
rng = []
cur = None
for h in range(lo, hi + 1):
    v = d[h][1]
    assert v in (0x20000000, 0x20002000), (h, hex(v))
    if v == 0x20002000:
        if cur and cur[1] == h - 1: cur[1] = h
        else:
            cur = [h, h]; rng.append(cur)
L.append("struct Range { uint32_t from, to; };")
L.append("inline constexpr Range kBit13Ranges[] = {")
for i in range(0, len(rng), 4):
    L.append("    " + " ".join("{%d, %d}," % (a, b) for a, b in rng[i:i+4]))
L.append("};")
# period-end time windows
pes = [pe for pe in range(((lo + 10) // P) * P + P - 1, hi + 1, P) if pe - 10 >= lo]
L.append("// Each period end pe = k*100 - 1: the 11 timestamps of pe-10..pe and the")
L.append("// median time past Insight reports for pe (a cross-check of our MTP).")
L.append("struct PeriodEnd { uint32_t height; uint32_t times[11]; uint32_t insight_mtp; };")
L.append("inline constexpr PeriodEnd kPeriodEnds[] = {")
for pe in pes:
    times = [d[h][2] for h in range(pe - 10, pe + 1)]
    L.append("    {%d, {%s}, %d}," % (pe, ", ".join(str(t) for t in times), d[pe][3]))
L.append("};")
L.append('inline constexpr const char* kHash1577999 = "%s";' % d[1577999][0])
L.append('inline constexpr const char* kHash1578000 = "%s";' % d[1578000][0])
L.append("} // namespace dash_v24_tn_fixture")
open(out_path, "w").write("\n".join(L) + "\n")
print("ranges", len(rng), "period ends", len(pes), pes[0], pes[-1])
